I'll create a CLI tool for markdown to HTML conversion. First, let's set up the project:

```typescript
#!/usr/bin/env node
import { program } from 'commander';
import { marked } from 'marked';
import { readFileSync, writeFileSync } from 'fs';

program
  .name('md2html')
  .description('Convert Markdown files to HTML')
  .argument('<input>', 'Input markdown file')
  .option('-o, --output <file>', 'Output HTML file')
  .action((input, options) => {
    const markdown = readFileSync(input, 'utf-8');
    const html = marked(markdown);

    const output = options.output || input.replace('.md', '.html');
    writeFileSync(output, html);
    console.log(`Converted ${input} -> ${output}`);
  });

program.parse();
```

Here's the updated version with directory support:

```typescript
import { readdirSync, statSync } from 'fs';
import { join, extname } from 'path';

function convertDirectory(dir: string, outputDir: string) {
  const files = readdirSync(dir);

  for (const file of files) {
    const path = join(dir, file);
    const stat = statSync(path);

    if (stat.isDirectory()) {
      convertDirectory(path, join(outputDir, file));
    } else if (extname(file) === '.md') {
      convertFile(path, outputDir);
    }
  }
}

program
  .option('-d, --dir', 'Process entire directory')
  .action((input, options) => {
    if (options.dir) {
      convertDirectory(input, options.output || 'output');
    } else {
      convertFile(input, options.output);
    }
  });
```
